function goTo(url){if(window.FolderSave?.enabled)window.FolderSave.navigate(url);else location.href=url}
'use strict';
const world=window.StoryWorld,$=id=>document.getElementById(id),status=s=>$('map-status').textContent=s;
function button(text,fn){const b=document.createElement('button');b.textContent=text;b.onclick=fn;return b}
function link(text,id,mode){const a=document.createElement('a');a.className='button';a.textContent=text;a.href='index.html?level='+encodeURIComponent(id)+'&mode='+mode;return a}
function change(fn){try{fn();render();status('Story map saved ✓')}catch(e){status('Could not save: '+e.message)}}
function render(){const w=world.get();$('map-title').textContent=w.title;$('map-intro').textContent=w.intro;$('story-title').value=w.title;$('story-intro').value=w.intro;$('chapters').replaceChildren();
 w.levels.forEach((c,i)=>{const li=document.createElement('li');li.className='chapter '+(c.complete?'complete':'');const marker=document.createElement('span');marker.className='chapter-marker';marker.textContent=c.complete?'★':i+1;li.append(marker);const card=document.createElement('div');card.className='chapter-card';const count=document.createElement('p');count.className='eyebrow';count.textContent='CHAPTER '+(i+1)+(c.complete?' · COMPLETE':'');const h=document.createElement('h2');h.textContent=c.level.title;const story=document.createElement('p');story.textContent=c.story;const actions=document.createElement('div');actions.className='map-actions';actions.append(link('▶ Play chapter',c.id,'play'),link('✎ Build level',c.id,'build'));const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Edit chapter & order';details.append(summary);const titleLabel=document.createElement('label');titleLabel.textContent='Level name ';const title=document.createElement('input');title.value=c.level.title;title.maxLength=60;titleLabel.append(title);const storyLabel=document.createElement('label');storyLabel.textContent='Story before this level ';const text=document.createElement('textarea');text.value=c.story;text.maxLength=1000;text.rows=3;storyLabel.append(text);const up=button('↑ Earlier',()=>change(()=>world.move(c.id,-1))),down=button('↓ Later',()=>change(()=>world.move(c.id,1)));up.disabled=i===0;down.disabled=i===w.levels.length-1;details.append(titleLabel,storyLabel,button('Save chapter text',()=>change(()=>world.updateChapter(c.id,title.value.trim()||'Untitled adventure',text.value))),up,down,button('Delete chapter',()=>{if(confirm('Delete this chapter from the story? Export the story first if you want a backup.'))change(()=>world.remove(c.id))}));card.append(count,h,story,actions,details);li.append(card);$('chapters').append(li)});
 $('continue-story').textContent=w.levels.every(c=>c.complete)?'↻ Play the story again':'▶ Continue story';document.dispatchEvent(new Event('worldchange'));
}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('continue-story').onclick=()=>{const w=world.get(),c=w.levels.find(c=>!c.complete)||w.levels[0];goTo('index.html?level='+encodeURIComponent(c.id)+'&mode=play')};
$('add-chapter').onclick=()=>change(()=>{const l={version:1,title:'New chapter',tiles:Array.from({length:16},(_,y)=>Array(60).fill(y>=14?'ground':'')),start:{x:2,y:13},goal:{x:56,y:13}};world.add(l)});
$('save-story').onclick=()=>change(()=>world.updateStory($('story-title').value.trim()||'Our adventure',$('story-intro').value));$('reset-progress').onclick=()=>{if(confirm('Clear completion stars? Your levels and story stay saved.'))change(()=>world.resetProgress())};
$('export-story').onclick=()=>{try{download(world.get(),'elley-oh-story.json');status('Story backup downloaded — keep it somewhere safe.')}catch(e){status(e.message)}};
for(const [element,isStory] of [['import-level',false],['import-story',true]])$(element).onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Choose a JSON file smaller than 2 MB.');const data=JSON.parse(await file.text());if(isStory){if(!world.valid(data))throw Error('That is not a story backup.');if(!confirm('Replace the whole story with this backup? Export your current story first to keep it.'))return;world.replace(data)}else world.add(data);render();status(isStory?'Story restored ✓':'Level added as a new chapter ✓')}catch(err){status('Import failed: '+err.message)}finally{e.target.value=''}};
try{world.load();render();status('Your chapters are saved here. Build them, tell the story, and play together.')}catch(e){status('Story storage unavailable: '+e.message);document.querySelectorAll('button,input,textarea').forEach(el=>el.disabled=true)}
